package com.bramble.dash.assets

import com.badlogic.gdx.utils.JsonReader
import com.badlogic.gdx.utils.ObjectMap

/**
 * Pure data view of assets/data/sprites.json (generated by tools/asset_pipeline.py from the pack's
 * metadata). Coordinates are bottom-left local pixels of the original, untrimmed canvas.
 */
class RegionMeta(
    val origW: Float, val origH: Float,
    val pivotX: Float, val pivotY: Float,
    val collX: Float, val collY: Float, val collW: Float, val collH: Float,
    val collEnabled: Boolean,
)

class AnimMeta(val name: String, val frameDuration: Float, val loop: Boolean, val frames: List<String>)

class SpriteData private constructor(
    private val regions: ObjectMap<String, RegionMeta>,
    private val anims: ObjectMap<String, AnimMeta>,
    val atlases: Map<String, String>,
) {
    fun region(name: String): RegionMeta = regions.get(name) ?: error("Unknown sprite region '$name'")
    fun hasRegion(name: String) = regions.containsKey(name)
    fun anim(name: String): AnimMeta = anims.get(name) ?: error("Unknown animation '$name'")
    fun hasAnim(name: String) = anims.containsKey(name)
    fun regionNames(): List<String> = regions.keys().toList()
    fun animNames(): List<String> = anims.keys().toList()

    /** Atlas group that holds a region, e.g. "char_max" for "characters/max/idle/00". */
    fun groupOf(region: String): String {
        val p = region.split('/')
        return when (p[0]) {
            "characters" -> "char_" + p[1]
            "enemies" -> "enemy_" + p[1]
            "bosses" -> "boss_" + p[1]
            "environments" -> "world_" + p[1]
            "collectibles", "powerups" -> "items"
            "obstacles", "effects" -> p[0]
            "ui" -> if (p[1] == "screens") "ui_panels" else "ui"
            "previews" -> "previews"
            else -> error("No atlas group for $region")
        }
    }

    companion object {
        fun parse(json: String): SpriteData {
            val root = JsonReader().parse(json)
            val regions = ObjectMap<String, RegionMeta>()
            var r = root.get("regions").child
            while (r != null) {
                val a = r.asFloatArray()
                regions.put(r.name, RegionMeta(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7], a[8] > 0f))
                r = r.next
            }
            val anims = ObjectMap<String, AnimMeta>()
            var an = root.get("anims").child
            while (an != null) {
                val frames = an.get(2).asStringArray().toList()
                anims.put(an.name, AnimMeta(an.name, an.getFloat(0), an.getInt(1) == 1, frames))
                an = an.next
            }
            val atlases = HashMap<String, String>()
            var at = root.get("atlases").child
            while (at != null) {
                atlases[at.name] = at.asString()
                at = at.next
            }
            return SpriteData(regions, anims, atlases)
        }
    }
}
